// Liest /admin/list und /date/list vollstaendig und gibt ausschliesslich
// die fuer Trainerzuordnung erforderlichen, datenschutzarmen Felder weiter.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;
if (!token || !edid) throw new Error('Token oder edid fehlt.');

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};
const basis = 'https://app1.edoobox.com/v2';

function rowsAus(body) {
  const d = body?.data;
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') return Object.values(d);
  return [];
}

async function holeAlle(pfad) {
  const alle = [];
  const reply = 2000;
  let start = 0;
  let total = null;
  for (let seite = 1; seite <= 20; seite += 1) {
    const a = await this.helpers.httpRequest({
      method: 'GET', url: basis + pfad, headers,
      qs: { 'limit[start]': start, 'limit[reply]': reply },
      json: true, returnFullResponse: true, timeout: 60000,
      ignoreHttpStatusErrors: true,
    });
    if (!(a.statusCode >= 200 && a.statusCode < 300)) throw new Error(`${pfad}: HTTP ${a.statusCode}`);
    const rows = rowsAus(a.body);
    if (total === null && a.body?.limit?.total !== undefined) total = Number(a.body.limit.total);
    alle.push(...rows);
    start += rows.length;
    if (rows.length === 0 || rows.length < reply || (total !== null && start >= total)) break;
  }
  if (total !== null && alle.length !== total) throw new Error(`${pfad}: gemeldet ${total}, gelesen ${alle.length}`);
  return alle;
}

const adminRoh = await holeAlle.call(this, '/admin/list');
const dateRoh = await holeAlle.call(this, '/date/list');

const admins = adminRoh.map(a => ({
  admin_id: String(a.id),
  shortcut: a.shortcut || null,
  permission: a.permission || null,
  is_active: a.status === true,
}));

const dates = dateRoh.map(d => ({
  date_id: String(d.id),
  offer_id: String(d.offer),
  date_start: d.date_start || null,
  date_end: d.date_end || null,
  place_ref: d.place || null,
  room_ref: d.room || null,
  leaders: [...new Set((Array.isArray(d.leader) ? d.leader : []).filter(Boolean).map(String))],
}));

return [{ json: {
  schritt: 'S54',
  adminsJson: JSON.stringify(admins),
  datesJson: JSON.stringify(dates),
  admins: admins.length,
  dates: dates.length,
  leaders: dates.reduce((s, d) => s + d.leaders.length, 0),
} }];
